// SPDX-License-Identifier: MIT
// Generate index.md, lessons/index.md, llms.txt and llms-full.txt from cases/*.md, lessons/*.md,
// checklist.md and pitfalls.md, and keep two things in step in hand-written files (SYNCED): the
// repository URL and the AI disclosure.
// Usage: node scripts/build.mjs          write the files
//        node scripts/build.mjs --check  write nothing; exit 1 if any generated file is out of date
// The case files and lesson pages are the source of truth; never edit the generated files by hand.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join, posix } from 'node:path';
import {
  ROOT, REPO_SLUG, REPO_SLUGS, LANGUAGES, LESSON_NOTE, LESSON_LEGEND, LESSON_PAGES, listCases, parseCase, loadLessons, lessonMeta, sub, linksIn, refDefs,
} from './lib.mjs';

const check = process.argv.includes('--check');
const REPO = `https://github.com/${REPO_SLUG}`;
const RAW_BASE = `https://raw.githubusercontent.com/${REPO_SLUG}/main`;
// Hand-written files that name this repository: the build rewrites any older slug in REPO_SLUGS
// (scripts/lib.mjs) to REPO_SLUG and leaves every other URL alone. README.md also gets the generated blocks in README_BLOCKS, each between its markers.
const SYNCED = ['README.md', 'CONTRIBUTING.md', 'LICENSE-CONTENT.md', 'docs/field-reports.md', '.github/ISSUE_TEMPLATE/config.yml',
  '.github/ISSUE_TEMPLATE/field-report.yml', 'lychee.toml'];
const GENERATED = '<!-- Generated by scripts/build.mjs from the case files and lesson pages. Do not edit by hand. -->';

const cases = listCases().map(parseCase)
  .sort((a, b) => (b.meta.date || '').localeCompare(a.meta.date || '') || a.file.localeCompare(b.file));
const pages = loadLessons();
const caseByFile = new Map(cases.map(c => [c.file, c]));

// The moves the cases cover, from each case's from_languages: every language with the companies that
// started from it, then the languages in LANGUAGES (scripts/lib.mjs) that no case starts from.
const byLanguage = new Map();
for (const c of cases) for (const x of [c.meta.from_languages].flat()) if (x && x !== 'unstated') byLanguage.set(x, [...(byLanguage.get(x) || []), c.meta.company]);
const joinList = (xs, word) => xs.length < 2 ? xs.join('') : `${xs.slice(0, -1).join(', ')} ${word} ${xs.at(-1)}`;
const orList = xs => joinList(xs, 'or');
const byName = (a, b) => a.localeCompare(b);
const uncovered = LANGUAGES.filter(x => !byLanguage.has(x)).sort(byName);
const langMoves = cases.filter(c => c.meta.kind === 'language').map(c => c.meta.company).sort(byName);
const unnamed = cases.filter(c => [c.meta.from_languages].flat().every(x => !x || x === 'unstated')).map(c => c.meta.company).sort(byName);
const COVERED =
  [...byLanguage.keys()].sort(byName).map(x => `${x} (${[...new Set(byLanguage.get(x))].sort(byName).join(', ')})`).join(', ') +
  '. Each case line below gives the move itself (from, to).' +
  ` Only ${joinList(langMoves, 'and')} changed the code's language; the others kept it (a framework, test, data, build or ` +
  'structure move).' +
  (unnamed.length ? ` Language not named: ${unnamed.join(', ')}.` : '') +
  (uncovered.length ? ` No case names ${orList(uncovered)} as the language it started from: lessons applied there are extrapolation.` : '');

// Build only from sources that parse; anything else would silently drop a case, a page or a count.
const broken = [
  ...cases.filter(c => c.error).map(c => `${c.file}: ${c.error}`),
  ...LESSON_PAGES.filter(s => !pages.some(p => p.slug === s)).map(s => `lessons/${s}.md: missing`),
  ...pages.flatMap(p => p.lessons.filter(l => !lessonMeta(l).oracle).map(l => `${p.file}: ${l.id}: no "Old system as oracle" line`)),
];
if (broken.length) {
  console.error(`cannot build; run node scripts/validate.mjs:\n${broken.map(b => '  ' + b).join('\n')}`);
  process.exit(1);
}

// One line per case, from the front matter only (AGENTS.md "One line per case").
const caseLine = (c, prefix) => {
  const m = c.meta;
  return `- [${m.title}](${prefix}${c.file}) — ${m.kind}, ${m.from} to ${m.to}; AI share: ${m.ai_share}; evidence: ${m.evidence}; ` +
    `author: ${m.author_relation}; cost: ${m.cost}. ${m.summary}`;
};

// Counts for one page or for all.
const count = lessons => {
  const by = (f, v) => lessons.filter(l => f(l) === v).length;
  return {
    n: lessons.length,
    stated: by(l => l.tag, 'stated'), ours: by(l => l.tag, 'ours'),
    yes: by(l => lessonMeta(l).oracle, 'yes'), partly: by(l => lessonMeta(l).oracle, 'partly'),
    no: by(l => lessonMeta(l).oracle, 'no'),
  };
};
const prefixOf = p => p.lessons[0]?.id.split('-')[0] ?? '';
const all = pages.flatMap(p => p.lessons);
const LEGEND = LESSON_LEGEND;
// Who wrote the text, and which cases involve the maker of the model that wrote it.
const claude = cases.filter(c => [c.meta.models].flat().some(m => /Claude/.test(m)));
const noModels = cases.filter(c => [c.meta.models].flat().every(m => !m || m === 'unstated'));
const DISCLOSURE = 'Disclosure: the cases and lessons are drafted by Claude, an Anthropic model, and reviewed by the ' +
  `maintainer. ${noModels.length ? 'At least ' : ''}${claude.length} of the ${cases.length} cases used Claude models (${claude.map(c => c.meta.company).join(', ')}` +
  `${noModels.length ? `; ${noModels.length} cases leave the models unstated` : ''}), ` +
  'and Anthropic owns Bun, the subject of one case.';

// The case files a lesson cites, in "Cases" or "Against", with the lesson IDs.
const caseFileOf = target => target?.match(/(?:^|\/)cases\/([^#/\s]+\.md)/)?.[1];
const caseUse = new Map(cases.map(c => [c.file, []]));
for (const p of pages) for (const l of p.lessons) {
  const files = new Set(['Cases', 'Against'].flatMap(s => linksIn(sub(l, s) || '', p.refs).map(x => caseFileOf(x.target))).filter(Boolean));
  for (const f of files) caseUse.get(f)?.push(l.id);
}

const out = {};

// lessons/index.md
{
  const t = count(all);
  const rows = pages.map(p => {
    const c = count(p.lessons);
    return `| [${p.title}](${p.slug}.md) | ${prefixOf(p)} | ${c.n} | ${c.stated} | ${c.ours} | ${c.yes} | ${c.partly} | ${c.no} |`;
  });
  const disagree = pages.flatMap(p => p.lessons.filter(l => /^Disagree:/.test(sub(l, 'Against') || ''))
    .map(l => `- **${l.id}** ([${p.title}](${p.slug}.md)) ${l.text}`));
  out['lessons/index.md'] = [
    GENERATED, '',
    '# Lessons by aspect', '',
    'Lessons for large engineering work done with AI agents, drawn from the case studies in [the case index](../index.md). Each ' +
      'lesson is one line in our own words with a stable ID (the prefix names its page), the cases behind it, the ' +
      'evidence against it, and whether it needs the old system as its oracle. The [checklist](../checklist.md) cites ' +
      'lessons by ID.', '',
    LESSON_NOTE, '',
    LEGEND, '',
    '## Aspects', '',
    '| Aspect | Prefix | Lessons | stated | ours | oracle yes | partly | no |',
    '| --- | --- | --- | --- | --- | --- | --- | --- |',
    ...rows,
    `| **All** | | ${t.n} | ${t.stated} | ${t.ours} | ${t.yes} | ${t.partly} | ${t.no} |`, '',
    '## Cases behind the lessons', '',
    'Lessons that cite each case, in "Cases" or "Against".', '',
    '| Case | Lessons |', '| --- | --- |',
    ...cases.map(c => `| [${c.meta.company}](../cases/${c.file}) | ${caseUse.get(c.file).length}: ${caseUse.get(c.file).join(', ') || 'none'} |`), '',
    '## Where the cases disagree', '',
    ...(disagree.length ? disagree : ['None recorded.']), '',
    '## Every lesson in one line', '',
    'To find the lessons that fit work other than a migration, scan this list, then open the pages of the lessons ' +
      'that fit. Each line: ID, tag, the lesson, then its oracle tag and strength.', '',
    ...pages.flatMap(p => [`### [${p.title}](${p.slug}.md)`, '',
      ...p.lessons.map(l => `- **${l.id}** [${l.tag}] ${l.text} (oracle: ${lessonMeta(l).oracle}; ${lessonMeta(l).strength})`), '']),
  ].join('\n');
}

// index.md
out['index.md'] = [
  GENERATED, '',
  '# Index', '',
  `${cases.length} cases, newest first. Each line: title — kind, from to to; the share of the changed code AI produced, as the source states it (a contrast case, mostly rule-based, says so in its summary); how far the claims can be checked; ` +
    'the author\'s stake in the tools; the cost the source gives; a one-line summary.', '',
  `Lessons drawn from the cases, by aspect: [lessons/index.md](lessons/index.md) (${all.length} lessons on ` +
    `${pages.length} pages). Before a migration: [checklist.md](checklist.md).`, '',
  ...cases.map(c => caseLine(c, 'cases/')), '',
].join('\n');

// Absolute links for llms-full.txt: reference links become inline links, and relative targets
// (resolved from `base`) become RAW_BASE URLs, in links and in reference definitions. Anchors and
// other schemes stay.
const RELATIVE = '(?![a-z][a-z0-9+.-]*:|#)';
const toRaw = (base, rel) => `${RAW_BASE}/${posix.normalize(base ? `${base}/${rel}` : rel)}`;
const absolute = (text, refs, base = 'lessons') => text
  .replace(/\[([^\]]+)\]\[([^\]]*)\]/g, (m, t, l) => { const x = refs.get((l || t).toLowerCase()); return x ? `[${t}](${x})` : m; })
  .replace(new RegExp(`\\]\\(${RELATIVE}([^)\\s]+)\\)`, 'gi'), (_, rel) => `](${toRaw(base, rel)})`)
  .replace(new RegExp(`^(\\[[^\\]]+\\]:\\s*)${RELATIVE}(\\S+)`, 'gim'), (_, label, rel) => `${label}${toRaw(base, rel)}`);
// A whole hand-written page for llms-full.txt: links made absolute, headings one level down
// (outside code blocks) so they sit under the file's own title.
// A reference definition goes into llms-full.txt once: `absolute` has made its links inline, so a
// definition an earlier page already gave (same label, same target) is dropped; checklist.md and
// pitfalls.md share the case labels.
const defined = new Set();
const embed = rel => {
  let fence = false;
  const text = readFileSync(join(ROOT, rel), 'utf8').replace(/\r\n/g, '\n').trim();
  const dir = posix.dirname(rel) === '.' ? '' : posix.dirname(rel);
  return absolute(text, refDefs(text.split('\n')), dir).split('\n')
    .flatMap(l => {
      if (/^```/.test(l)) { fence = !fence; return [l]; }
      if (fence) return [l];
      const m = l.match(/^\[([^\]]+)\]:\s*(\S+)/);
      const def = m && `${m[1].toLowerCase()} ${m[2]}`;
      if (def) { if (defined.has(def)) return []; defined.add(def); return [l]; }
      return [/^#{1,5} /.test(l) ? `#${l}` : l];
    }).join('\n');
};

// llms-full.txt (built first: llms.txt states its size)
{
  // Each lesson with its sub-items, from the parsed page (whatever else sits between lessons).
  const lessonText = p => absolute(p.lessons.map(l => [p.lines[l.line - 1], ...l.subs.map(s => s.raw)].join('\n')).join('\n'), p.refs);
  out['llms-full.txt'] = [
    '# AI migrations: every lesson, every case line, the checklist and the pitfalls in one file', '',
    'Unofficial; company names describe the subject only. Summaries and lessons are our own words under CC BY 4.0. ' +
      `Source: ${REPO}`, '',
    DISCLOSURE, '',
    LESSON_NOTE.replace('[this collection](../index.md)', 'this collection'), '',
    LEGEND, '',
    ...pages.flatMap(p => [`## ${p.title} (${p.slug}.md)`, '', p.intro, '', lessonText(p), '']),
    '## Cases', '',
    ...cases.map(c => caseLine(c, `${RAW_BASE}/cases/`)), '',
    embed('checklist.md'), '',
    embed('pitfalls.md'), '',
  ].join('\n');
}
const fullKB = Math.round(Buffer.byteLength(out['llms-full.txt'], 'utf8') / 1024);
const fullKTokens = Math.round(Buffer.byteLength(out['llms-full.txt'], 'utf8') / 4000);
const indexKB = Math.round(Buffer.byteLength(out['lessons/index.md'], 'utf8') / 1024);

// llms.txt (https://llmstxt.org)
out['llms.txt'] = [
  '# AI migrations', '',
  '> Case studies of software migrations done with AI: what worked, what failed, and which part AI did versus ' +
    'rule-based tools and people. Lessons drawn from them by aspect (planning, testing, review, rollout, cost and ' +
    'more), and a before-you-migrate checklist an agent runs on a repository.', '',
  'Unofficial; company names describe the subject only. Every lesson comes from migrations; many apply to large ' +
    'engineering work done with AI agents generally. A lesson\'s "Old system as oracle" tag says whether its evidence ' +
    'leaned on the old system; it hints at how far the lesson travels but is not a filter, so judge each lesson by its ' +
    'own words. Each case says how far its claims can be checked and what stake its author has in the tools: weigh it ' +
    'accordingly; a lesson that rests only on cases whose authors sell the tool is never rated strong.', '',
  DISCLOSURE, '',
  `Moves covered, by the language the code was in before the move: ${COVERED}`, '',
  '## How to use', '',
  `- Before a migration or a large restructuring: run the [checklist](${RAW_BASE}/checklist.md) on the repository and change nothing. Each ` +
    'question has a Check to measure and cites lesson IDs; open only the lessons and cases behind a gap.',
  '- For any other large piece of AI-driven work: scan the one-line list of every lesson at the end of ' +
    `[lessons/index.md](${RAW_BASE}/lessons/index.md) (about ${indexKB} KB), then open the aspect pages of the lessons ` +
    'that fit (each lesson there has its cases, the evidence against it, and its oracle and strength).',
  `- Open a case only when you need its detail. Each has "Who did what", "How it was checked", a Numbers table with ` +
    `the basis of each number, "What went wrong" and "Practices to copy". File format: [AGENTS.md](${RAW_BASE}/AGENTS.md).`,
  `- After a review, a migration or a revisit: tell what the checklist or the lessons foresaw and what they missed, ` +
    `in a field report ([how](${RAW_BASE}/docs/field-reports.md)); show the user the exact text before posting.`,
  `- Relative links inside these files resolve against ${RAW_BASE}/.`, '',
  '## Lessons', '',
  ...pages.map(p => {
    const c = count(p.lessons);
    return `- [${p.title}](${RAW_BASE}/lessons/${p.slug}.md): ${c.n} lessons, ${prefixOf(p)}-n (${c.stated} stated, ` +
      `${c.ours} ours; oracle: ${c.yes} yes, ${c.partly} partly, ${c.no} no). ${p.intro}`;
  }), '',
  '## Cases', '',
  ...cases.map(c => caseLine(c, `${RAW_BASE}/cases/`)), '',
  '## Optional', '',
  `- [Everything in one file](${RAW_BASE}/llms-full.txt): every lesson, every case line, the checklist and the ` +
    `pitfalls, for tools that cannot follow links. About ${fullKB} KB (~${fullKTokens}k tokens), so prefer the ` +
    'aspect pages when you can.',
  `- [Pitfalls by kind of move](${RAW_BASE}/pitfalls.md): what the old stack did implicitly, and seams for moving in steps.`,
  `- [Lessons index](${RAW_BASE}/lessons/index.md): counts, the cases behind each lesson, and where the cases disagree.`,
  `- [Update log](${RAW_BASE}/log.md): what each update covered and changed; on a revisit, read the entries newer than your record.`, '',
].join('\n');

// Hand-written files kept in step: this repository's URLs, and README's generated blocks.
const questions = (readFileSync(join(ROOT, 'checklist.md'), 'utf8').match(/^\d+\. \*\*/gm) || []).length;
const README_BLOCKS = {
  disclosure: DISCLOSURE,
  contents: `Now: ${cases.length} cases (${[...cases].reverse().map(c => c.meta.company).join(', ')}), ${all.length} lessons on ` +
    `${pages.length} aspect pages, and a checklist of ${questions} questions.`,
};
for (const rel of SYNCED) {
  const p = join(ROOT, rel);
  if (!existsSync(p)) continue;
  let t = readFileSync(p, 'utf8').replace(/\r\n/g, '\n');
  for (const old of REPO_SLUGS.slice(1)) t = t.split(old).join(REPO_SLUG);
  if (rel === 'README.md') {
    for (const [name, text] of Object.entries(README_BLOCKS)) {
      const a = `<!-- ${name}: generated by scripts/build.mjs -->`, z = `<!-- /${name} -->`;
      const i = t.indexOf(a), j = t.indexOf(z);
      if (i < 0 || j < i) { console.error(`README.md: needs the markers ${a} and ${z}`); process.exit(1); }
      t = `${t.slice(0, i + a.length)}\n${text}\n${t.slice(j)}`;
    }
  }
  out[rel] = t;
}

// Write or check.
const stale = [];
for (const [rel, content] of Object.entries(out)) {
  const p = join(ROOT, rel);
  const old = existsSync(p) ? readFileSync(p, 'utf8').replace(/\r\n/g, '\n') : null;
  if (old === content) continue;
  stale.push(rel);
  if (!check) writeFileSync(p, content);
}
if (check && stale.length) {
  console.error(`out of date: ${stale.join(', ')}\nrun: node scripts/build.mjs`);
  process.exit(1);
}
console.log(check ? `generated files up to date (${Object.keys(out).length}).`
  : `${stale.length ? 'wrote ' + stale.join(', ') : 'nothing to write'}: ${cases.length} cases, ${all.length} lessons on ${pages.length} pages.`);
if (!check) for (const f of caseByFile.keys()) if (!caseUse.get(f).length) console.warn(`note: no lesson cites ${f}`);
